//! ComfyUI (issue 512): images generated by a ComfyUI server, with the workflows the operator
//! configured (`workflow`), by the tool of the component kind `comfyui_tool` (`tool`) over a client
//! of the server (`client`), and the plugin that joins them to the runtime (`plugin`). A crate of
//! its own, so that a program that reaches no ComfyUI server need not build it.

mod client;
pub mod plugin;
mod tool;
pub mod workflow;

#[cfg(test)]
use caelumora_agents::testing;
#[cfg(test)]
use caelumora_model::prompt_catalogue::PromptTexts;

/// The namespace of the texts of ComfyUI's tool in the prompt catalogue (issue 57).
pub(crate) const NAMESPACE: &str = "comfyui";

/// Their texts, added to the catalogue under `NAMESPACE` by the plugin.
pub(crate) const PROMPTS: &str = include_str!("prompts.yaml");

/// The texts of the core, of the agents and of this tool, as the runtime and the plugins add
/// them - for what a test makes itself.
#[cfg(test)]
pub(crate) fn prompts() -> PromptTexts {
    testing::prompts_with(NAMESPACE, PROMPTS)
}
